}

// ScrapeFoodData scraps data from a website and returns a list of Food objects
func ScrapeFoodData(url string) []Food {
	// Make an HTTP GET request to the website
	resp, err := http.Get(url)
	if err != nil {
		log.Fatal(err)
	}
	defer resp.Body.Close()

	// Parse the HTML data using the parser package
	doc, err := parser.Parse(resp.Body)
	if err != nil {
		log.Fatal(err)
	}

	// Extract the nutritional and ingredient information from the HTML data
	var foods []Food
